// A simple matrix type: row-major storage as Vec<Vec<T>>
pub type Matrix<T> = Vec<Vec<T>>;

pub fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    assert!(!a.is_empty(), "input array must have positive length");
    assert!(shape.len() == 2, "shape must have length 2");

    let r = shape[0] as usize;
    let c = shape[1] as usize;
    assert!(r > 0 && c > 0, "both shape entries must be positive");

    let n = a.len();
    assert!(
        n == r || n == c,
        "array length must equal either R or C for broadcasting"
    );

    if n == r {
        // Treat as column vector: out[i][j] = a[i]
        let mut out: Matrix<i8> = Vec::with_capacity(r);
        for i in 0..r {
            let mut row = Vec::with_capacity(c);
            row.resize(c, a[i]);
            out.push(row);
        }
        out
    } else {
        // Treat as row vector: out[i][j] = a[j]
        let mut out: Matrix<i8> = Vec::with_capacity(r);
        for _ in 0..r {
            out.push(a.clone());
        }
        out
    }
}